import java.io.*;
import java.util.*;

public class F5 {

	long[][] ways;
	long totalWays;
	long bestDiff = Long.MAX_VALUE;
	long ans = 0;
	BufferedReader br;
	StringTokenizer st;
	PrintWriter out;

	static class Half {
		long match;
		long value;

		Half(long match, long value) {
			this.match = match;
			this.value = value;
		}
	}

	long solve(int r, int c, String s) {
		bestDiff = Long.MAX_VALUE;
		ans = 0;

		long maskA = 0;
		long maskB = 0;
		int[][] cnt = new int[s.length() + 1][2];
		for (int i = 0; i < s.length(); i++) {
			cnt[i + 1] = cnt[i].clone();
			if (s.charAt(i) == 'A') {
				cnt[i + 1][0]++;
				maskA |= 1L << i;
			}
			if (s.charAt(i) == 'B') {
				cnt[i + 1][1]++;
				maskB |= 1L << i;
			}
		}

		long lastA = maskA >> (2 * r + c - 1);
		long lastB = maskB >> (2 * r + c - 1);

		Half[][] fst = new Half[c + 2][];
		Half[][] snd = new Half[c + 2][];
		int[] sz = new int[c + 2];
		for (int i = 0; i < c + 2; i++) {
			sz[i] = (int) ways[c + 1][i];
			fst[i] = new Half[sz[i]];
			snd[i] = new Half[sz[i]];
		}

		for (int mask = 0; mask < 1 << (c + 1); mask++) {
			int btc = Integer.bitCount(mask);
			int compBtc = c + 1 - btc;
			int idx = --sz[btc];

			{
				int samePref = Math.min(Integer
						.numberOfTrailingZeros((mask & 1) == 0 ? mask
								: (mask + 1)), c + 1);

				int totalA = r - 1 - cnt[2 * r - 2 + samePref][0];
				int totalB = r - 1 - cnt[2 * r - 2 + samePref][1];
				if ((mask & 1) == 0) {
					totalA += samePref;
				} else {
					totalB += samePref;
				}

				long winsA = 0;

				int curA = 0;
				int curB = 0;
				for (int i = 0; i < c + 1; i++) {
					if (test(mask, i)) {
						winsA += ways[r - 1 + curB][r - 1]
								* choose(r - 1 + curA, r);
						curB++;
					} else {
						curA++;
					}
				}

				int exactMatch = 1;
				for (int i = samePref; i < c + 1; i++) {
					if (!test(mask, i) && s.charAt(2 * r - 2 + i) == 'B') {
						exactMatch = 0;
						break;
					}
					if (test(mask, i) && s.charAt(2 * r - 2 + i) == 'A') {
						exactMatch = 0;
						break;
					}
				}

				fst[btc][idx] = new Half(choose(totalA + totalB, totalA)
						* exactMatch, winsA);
			}

			{
				int match = 1;
				if (((~mask) & lastB) != 0) {
					match = 0;
				}
				if ((mask & lastA) != 0) {
					match = 0;
				}

				long winsA = 0;

				int curA = btc;
				int curB = compBtc;
				for (int i = 0; i < c + 1; i++) {
					if (test(mask, i)) {
						winsA += ways[r - 1 + curB][r - 1]
								* choose(r - 1 + curA, r);
						curB++;
					} else {
						curA++;
					}
				}

				snd[btc][idx] = new Half(match, winsA);
			}
		}

		totalWays = ways[r + c][r] * ways[r + c][r];
		long halfTotal = totalWays / 2;

		for (int i = 0; i <= c + 1; i++) {
			NavigableMap<Long, Long> one = compress(fst[i]);
			NavigableMap<Long, Long> two = compress(snd[c + 1 - i]);

			for (Map.Entry<Long, Long> a : one.entrySet()) {
				long aValue = a.getKey();
				long aMatch = a.getValue();
				long remaining = halfTotal - aValue;

				Map.Entry<Long, Long> floor = two.floorEntry(remaining);
				if (floor != null) {
					update(new Half(aMatch, aValue), new Half(floor.getValue(), floor.getKey()));
				}

				Map.Entry<Long, Long> higher = two.higherEntry(remaining);
				if (higher != null) {
					update(new Half(aMatch, aValue), new Half(higher.getValue(), higher.getKey()));
				}
			}
		}
		return ans;
	}

	void submit() {
		int r = nextInt();
		int c = nextInt();
		String s = nextToken();
		out.println(solve(r, c, s));
	}

	NavigableMap<Long, Long> compress(Half[] arr) {
		NavigableMap<Long, Long> map = new TreeMap<>();
		for (Half h : arr) {
			map.put(h.value, map.getOrDefault(h.value, 0L) + h.match);
		}
		return map;
	}

	void update(Half a, Half b) {
		long totalValue = a.value + b.value;
		long diff = Math.abs(2 * totalValue - totalWays);
		long delta = a.match * b.match;
		if (diff < bestDiff) {
			bestDiff = diff;
			ans = delta;
		} else if (diff == bestDiff) {
			ans += delta;
		}
	}

	long choose(int n, int k) {
		return n >= 0 && k >= 0 && k <= n ? ways[n][k] : 0;
	}

	static boolean test(int mask, int i) {
		return ((mask >> i) & 1) == 1;
	}

	void preCalc() {
		ways = new long[61][];
		for (int i = 0; i < ways.length; i++) {
			ways[i] = new long[i + 1];
			ways[i][0] = ways[i][i] = 1;
			for (int j = 1; j < i; j++) {
				ways[i][j] = ways[i - 1][j - 1] + ways[i - 1][j];
			}
		}
	}

	F5() throws IOException {
		br = new BufferedReader(new InputStreamReader(System.in));
		out = new PrintWriter(System.out);
		preCalc();
		submit();
		out.close();
	}

	public static void main(String[] args) throws IOException {
		new F5();
	}

	String nextToken() {
		while (st == null || !st.hasMoreTokens()) {
			try {
				st = new StringTokenizer(br.readLine());
			} catch (IOException e) {
				throw new RuntimeException(e);
			}
		}
		return st.nextToken();
	}

	int nextInt() {
		return Integer.parseInt(nextToken());
	}
}
